import{_ as r,C as i,o as a,c as s,a2 as l,b as A,w as e,a as E,E as n,a3 as C}from"./chunks/framework.BBdhqAg0.js";const B="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",f=JSON.parse('{"title":"직원 인사 관리","description":"","frontmatter":{},"headers":[],"relativePath":"hr-manage/staff.md","filePath":"hr-manage/staff.md","lastUpdated":1793111736000}'),u={name:"hr-manage/staff.md"};function g(d,t,c,_,p,m){const o=i("Mermaid");return a(),s("div",null,[t[1]||(t[1]=l('<h1 id="직원-인사-관리" tabindex="-1">직원 인사 관리 <a class="header-anchor" href="#직원-인사-관리" aria-label="Permalink to &quot;직원 인사 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+B+'" alt="직원 인사 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/staff.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>직원 인사 관리</strong>는 임직원의 기초 인적 사항, 로그인 계정 연동, 고용 형태(정규직/계약직/위촉직 등)를 관리하고, 부서 발령·보직 이동·승진 등의 인사 이력을 영구적으로 기록·보관하는 본사 인사 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[본사 관리] → [인사 조직 관리] → [직원 인사 관리]**를 선택하여 접속합니다. (인사 담당자 및 관리자 권한 필요)</li></ul>',4)),(a(),A(C,null,{default:e(()=>[n(o,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%F0%9F%91%A4%20%EB%A1%9C%EA%B7%B8%EC%9D%B8%20%EC%82%AC%EC%9A%A9%EC%9E%90%20%EA%B3%84%EC%A0%95%3Cbr%3E(%EC%8B%9C%EC%8A%A4%ED%85%9C%20%EC%A0%91%EA%B7%BC%20%EA%B6%8C%ED%95%9C)%22%5D%20%3C--%3E%20B%5B%22%F0%9F%A7%91%E2%80%8D%F0%9F%92%BC%20%EC%A7%81%EC%9B%90%20%EC%9D%B8%EC%82%AC%20%ED%94%84%EB%A1%9C%ED%95%84%3Cbr%3E(%EC%9D%B8%EC%A0%81%20%EC%82%AC%ED%95%AD%C2%B7%EB%B6%80%EC%84%9C%C2%B7%EC%A7%81%EA%B8%89)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%8F%A2%20%EB%B3%B4%EC%A7%81%20%EB%B0%8F%20%EC%9D%B8%EC%82%AC%20%EB%B0%9C%EB%A0%B9%3Cbr%3E(%EC%A3%BC%EB%B3%B4%EC%A7%81%C2%B7%EA%B2%B8%EC%A7%81%20%EA%B4%80%EB%A6%AC)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%93%8B%20%EC%9D%B8%EC%82%AC%20%EC%9D%B4%EB%A0%A5%20%EB%8C%80%EC%9E%A5%3Cbr%3E(%EC%8A%B9%EC%A7%84%C2%B7%ED%8F%AC%EC%83%81%C2%B7%EB%B3%80%EB%8F%99%20%EB%82%B4%EC%97%AD)%22%5D%0A%20%20%20%20B%20--%3E%20E%5B%22%F0%9F%93%91%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%20%26%20%ED%98%91%EC%97%85%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%B0%B8%EC%97%AC%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_1-직원-정보-관리-staff" tabindex="-1">1. 직원 정보 관리 (Staff) <a class="header-anchor" href="#_1-직원-정보-관리-staff" aria-label="Permalink to &quot;1. 직원 정보 관리 (Staff)&quot;">​</a></h2><p>임직원의 기본 정보(성명, 생년월일, 연락처, 입사일, 재직 상태)를 등록하고 시스템 로그인 계정과 1:1로 매핑합니다.</p><ul><li><strong>사용자 계정 1:1 매핑</strong>: <ul><li>시스템 로그인 계정과 직원 인사 레코드를 연결하여, 로그인 시 본인의 인사 정보, 잔여 휴가 현황, 결재 권한이 자동으로 동기화됩니다.</li></ul></li><li><strong>고용 형태 세분화</strong>: <ul><li>정규직, 계약직/기간제, 파견직, 위촉직/자문, 인턴/수습, 파트타임 등 고용 형태를 구분하여 관리하며, 계약직의 경우 계약 만료일을 설정하여 사전에 갱신 시점을 관리할 수 있습니다.</li></ul></li><li><strong>재직 상태 제어</strong>: <ul><li><strong>재직 (정상)</strong>: 정상 근무 상태로, 모든 시스템 접근 및 전자결재 권한이 활성화됩니다.</li><li><strong>휴직</strong>: 육아 휴직, 질병 휴직 등으로 업무 및 결재 권한이 일시 정지됩니다.</li><li><strong>퇴직 (퇴사)</strong>: 퇴사일이 기록되며 시스템 로그인이 즉시 차단되고, 과거 작성된 결재 및 업무 이력은 영구 보존됩니다.</li></ul></li></ul><h2 id="_2-임원-정보-관리-executive" tabindex="-1">2. 임원 정보 관리 (Executive) <a class="header-anchor" href="#_2-임원-정보-관리-executive" aria-label="Permalink to &quot;2. 임원 정보 관리 (Executive)&quot;">​</a></h2><p>회사의 등기 임원 및 미등기 임원에 대한 직무 구분, 선임일, 임기 만료일, 주주총회/이사회 이력을 독립적으로 관리합니다.</p><ul><li><strong>임기 및 중임 관리</strong>: 임원별 임기 시작일과 만료일을 기록하여 중임/퇴임 시점을 체계적으로 관리합니다.</li><li><strong>전결 규정 연동</strong>: 대표이사 및 담당 임원의 결재 전결 규정과 연동되어 고액 사업비 지출 및 중요 계약 품의 시 필수 최종 승인선으로 자동 지정됩니다.</li></ul><h2 id="_3-인사-발령-관리-appointments" tabindex="-1">3. 인사 발령 관리 (Appointments) <a class="header-anchor" href="#_3-인사-발령-관리-appointments" aria-label="Permalink to &quot;3. 인사 발령 관리 (Appointments)&quot;">​</a></h2><p>신규 입사, 부서 이동, 전보, 승진, 겸직 등 조직 개편 및 인사이동 시 발령을 등록하고 일괄 적용합니다.</p><ul><li><strong>주보직 및 겸직 지원</strong>: <ul><li>직원은 기본적으로 하나의 주보직(소속 부서 및 직책)을 가지며, 특정 프로젝트 파견이나 태스크포스(TF) 등에 따른 겸직을 복수로 부여받을 수 있습니다.</li><li>전자결재 기안 시 상신 보직을 선택할 수 있어 본사 부서 결재선과 프로젝트 결재선을 유연하게 구분하여 상신할 수 있습니다.</li></ul></li><li><strong>발령 적용 시점 지정</strong>: <ul><li>발령 예정 일자를 사전 등록해 두면 정기 인사 발령 당일에 맞추어 조직도와 전자결재선이 자동으로 갱신됩니다.</li></ul></li></ul><h2 id="_4-인사-이력-관리-records" tabindex="-1">4. 인사 이력 관리 (Records) <a class="header-anchor" href="#_4-인사-이력-관리-records" aria-label="Permalink to &quot;4. 인사 이력 관리 (Records)&quot;">​</a></h2><p>입사부터 퇴사까지 임직원의 모든 신분 변동 내역(승진, 보직 변경, 포상, 징계, 휴직 등)을 시계열로 영구 보관합니다.</p><ul><li><strong>자동 이력 스냅샷 생성</strong>: 인사 발령이 승인되는 즉시 변경 전/후 부서, 직급, 직책 정보가 인사 이력 대장에 자동으로 기록되어 변경 이력의 위변조를 방지합니다.</li><li><strong>인사 기록 카드 출력</strong>: 필요 시 직원의 전체 재직 이력을 한눈에 볼 수 있는 &#39;인사 기록 카드&#39; 양식으로 조회하고 인쇄할 수 있습니다.</li></ul><h2 id="_5-실무-운영-가이드" tabindex="-1">5. 실무 운영 가이드 <a class="header-anchor" href="#_5-실무-운영-가이드" aria-label="Permalink to &quot;5. 실무 운영 가이드&quot;">​</a></h2><ul><li><strong>신입사원 온보딩 시 계정 연동 (인사 담당자 필독 ⭐️)</strong>: <ol><li>먼저 <a href="/work-setting/user.html">설정 관리 &gt; 사용자</a> 메뉴에서 신입사원의 시스템 로그인 계정을 생성합니다.</li><li>본 <strong>직원 인사 관리</strong> 화면에서 [직원 추가] 버튼을 누르고, 기본 인적 사항을 입력한 뒤 방금 생성한 로그인 계정을 매핑합니다.</li><li>주보직 발령(소속 부서, 직위, 직책)을 등록하면 신입사원의 온보딩 세팅이 완료됩니다.</li></ol></li><li><strong>퇴사자 처리 원칙</strong>: <ul><li>직원이 퇴사하는 경우 프로필을 삭제하지 않고 <strong>재직 상태를 &#39;퇴직&#39;으로 변경</strong>하십시오. 이렇게 해야 퇴사자가 과거에 결재하거나 기안한 문서의 작성자 정보가 시스템에 안전하게 보존됩니다.</li></ul></li></ul>',14))])}const D=r(u,[["render",g]]);export{f as __pageData,D as default};
